def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    MOD = 998244353

    def mod_inv(a, p):
        return pow(a, p - 2, p)

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:n+2]))
    w = list(map(int, data[n+2:2*n+2]))

    total_weight = sum(w)

    for _ in range(m):
        new_w = [0] * n
        for i in range(n):
            if a[i] == 1:
                new_w[i] = w[i] + 1
            else:
                new_w[i] = w[i] - 1

        w = new_w
        total_weight = sum(w)

    p = [0] * n
    for i in range(n):
        p[i] = w[i] * mod_inv(total_weight, MOD) % MOD

    q = [0] * n
    for i in range(n):
        q[i] = w[i]

    r = [0] * n
    for i in range(n):
        r[i] = q[i] * mod_inv(p[i], MOD) % MOD

    print(' '.join(map(str, r)))
